"const API_BASE = import.meta.env.VITE_API_URL || 'http://localhost:8000';

export interface Message {
  id: string;
  role: 'user' | 'assistant';
  content: string;
  created_at: string;
}

export interface Session {
  id: string;
  title: string;
  created_at: string;
  updated_at: string;
  messages?: Message[];
}

export const api = {
  getSessions: async (): Promise<Session[]> => {
    const res = await fetch(`${API_BASE}/sessions`);
    return res.json();
  },

  createSession: async (title: string = "New Chat"): Promise<Session> => {
    const res = await fetch(`${API_BASE}/sessions`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ title })
    });
    return res.json();
  },

  getSession: async (id: string): Promise<Session> => {
    const res = await fetch(`${API_BASE}/sessions/${id}`);
    return res.json();
  },

  sendMessage: async (sessionId: string, message: string, provider: string): Promise<Message> => {
    const res = await fetch(`${API_BASE}/sessions/${sessionId}/chat`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ message, llm_provider: provider })
    });
    return res.json();
  }
};"

"import React, { useEffect, useRef } from 'react';
import ReactMarkdown from 'react-markdown';
import { Code, X } from 'lucide-react';

interface ArtifactViewerProps {
  content: string;
  onClose: () => void;
}

export const ArtifactViewer: React.FC<ArtifactViewerProps> = ({ content, onClose }) => {
  const isHtml = content.trim().startsWith('<') || content.includes('<html>') || content.includes('<!DOCTYPE');
  const iframeRef = useRef<HTMLIFrameElement>(null);

  useEffect(() => {
    if (isHtml && iframeRef.current) {
      // Sandbox restricts execution of scripts (no allow-scripts), but allows rendering layout.
      const blob = new Blob([content], { type: 'text/html' });
      const url = URL.createObjectURL(blob);
      iframeRef.current.src = url;

      return () => URL.revokeObjectURL(url);
    }
  }, [content, isHtml]);

  return (
    <div className="artifact-pane">
      <div className="artifact-header">
        <div style={{ display: 'flex', alignItems: 'center', gap: '0.5rem' }}>
          <Code size={16} />
          <span>{isHtml ? 'Web Component' : 'Markdown Essay'}</span>
        </div>
        <button onClick={onClose} style={{ background: 'none', border: 'none', color: 'inherit', cursor: 'pointer' }}>
          <X size={16} />
        </button>
      </div>
      <div className="artifact-content">
        {isHtml ? (
          <iframe 
            ref={iframeRef} 
            className="artifact-iframe" 
            sandbox="allow-same-origin" // Important: Scripts are NOT allowed
            title="Artifact Preview"
          />
        ) : (
          <div className="markdown-body">
            <ReactMarkdown>{content}</ReactMarkdown>
          </div>
        )}
      </div>
    </div>
  );
};"

